/**
 * Refresh the curated community-instance snapshot from searx.space.
 *
 * Usage (needs a network that reaches searx.space — run on your own machine):
 *   pnpm run update-instances   # or: make update-instances
 *
 * What it does:
 *   1. GET https://searx.space/data/instances.json (generated by the
 *      searx-stats2 checker; schema is NOT versioned, so everything below
 *      parses tolerantly).
 *   2. Keep https instances whose checker status is up (or unknown when the
 *      checker exposes no status field at all), sort uptime desc, latency
 *      asc, keep the top 100 (deep pool: the card probes in order and stops
 *      early once 10 usable rows are found).
 *   3. Write src/client/instances.snapshot.json — bundled into lib/client.js
 *      by esbuild, so the card works offline from the snapshot date.
 *
 * Caveats (also shown in the card):
 *   - The checker metadata does NOT record whether `?format=json` is enabled,
 *     so every community instance is "json unverified" until you save it and
 *     run `make smoke` / `make probe` against it.
 *   - Community instances see your query plaintext. Don't search sensitive
 *     topics through them; prefer self-hosting for that.
 */

const SOURCE = process.env.SEARXNG_SNAPSHOT_URL || 'https://searx.space/data/instances.json'
const OUT = new URL('../src/client/instances.snapshot.json', import.meta.url)
const KEEP = 100

const STATUS_KEYS = ['status', 'state', 'up', 'online']
const LATENCY_MS_KEYS = ['latencyMs', 'latency_ms']
const LATENCY_S_KEYS = ['itime', 'response_time', 'responseTime', 'time', 'latency']
const UPTIME_KEYS = ['uptime', 'uptimePct']
const UPTIME_NESTED_KEYS = ['all', 'week', 'day', 'month']
const VERSION_KEYS = ['version', 'searxng_version']

/**
 * Derive status from a searx-stats2 entry (real schema, observed 2026-09):
 *   entry.timing.{initial,search}.{success_percentage, all:{value}, error, working_engines}
 *   entry.http.{status_code, error}
 * Rules:
 *   - http.error set (checker could not connect at all) → down
 *   - initial.success_percentage === 0 → down (homepage unreachable)
 *   - search.success_percentage > 0 && working_engines > 0 → up
 *   - otherwise unknown (reachable homepage, but the checker's probe search
 *     returned nothing — common when engines throttle checker IPs; the
 *     instance may still serve real users, so keep it).
 */
function statusFromStats2(info) {
  const timing = asRecord(info.timing)
  const http = asRecord(info.http)
  if (http && typeof http.error === 'string' && http.error.trim() !== '') return 'down'
  const initial = timing ? asRecord(timing.initial) : undefined
  const search = timing ? asRecord(timing.search) : undefined
  const initPct = typeof initial?.success_percentage === 'number' ? initial.success_percentage : undefined
  if (initPct === 0) return 'down'
  const searchPct = typeof search?.success_percentage === 'number' ? search.success_percentage : undefined
  const working = typeof search?.working_engines === 'number' ? search.working_engines : undefined
  if (searchPct !== undefined && searchPct > 0 && (working === undefined || working > 0)) return 'up'
  // legacy flat status fields (older checker output)
  const legacy = normStatus(firstPresent(info, STATUS_KEYS))
  if (legacy !== 'unknown') return legacy
  return initPct !== undefined && initPct > 0 ? 'unknown' : 'unknown'
}

/** Availability % for ranking: search success % preferred, else initial %. */
function healthFromStats2(info) {
  const timing = asRecord(info.timing)
  const search = timing ? asRecord(timing.search) : undefined
  const initial = timing ? asRecord(timing.initial) : undefined
  const s = typeof search?.success_percentage === 'number' ? search.success_percentage : undefined
  if (s !== undefined) return Math.round(s * 10) / 10
  const i = typeof initial?.success_percentage === 'number' ? initial.success_percentage : undefined
  if (i !== undefined) return Math.round(i * 10) / 10
  return normUptime(firstPresent(info, UPTIME_KEYS))
}

/** Latency ms for ranking: timing.initial.all.value (seconds) preferred. */
function latencyFromStats2(info) {
  const timing = asRecord(info.timing)
  for (const section of [timing ? asRecord(timing.initial) : undefined, timing ? asRecord(timing.search) : undefined]) {
    const all = section ? asRecord(section.all) : undefined
    const v = all && typeof all.value === 'number' ? all.value : undefined
    if (v !== undefined && Number.isFinite(v) && v >= 0) return v < 300 ? Math.round(v * 1000) : Math.round(v)
  }
  return normLatency(info)
}

function asRecord(v) {
  return typeof v === 'object' && v !== null ? v : undefined
}

function firstPresent(entry, keys) {
  for (const k of keys) {
    if (entry[k] !== undefined && entry[k] !== null) return entry[k]
  }
  return undefined
}

function normStatus(v) {
  if (v === true || v === 1) return 'up'
  if (v === false || v === 0) return 'down'
  if (typeof v !== 'string') return 'unknown'
  const s = v.trim().toLowerCase()
  if (['up', 'online', 'ok', 'success', 'true'].includes(s)) return 'up'
  if (['down', 'offline', 'error', 'fail', 'failed', 'false'].includes(s)) return 'down'
  return 'unknown'
}

function normLatency(entry) {
  const ms = firstPresent(entry, LATENCY_MS_KEYS)
  if (typeof ms === 'number' && Number.isFinite(ms) && ms >= 0) return Math.round(ms)
  const s = firstPresent(entry, LATENCY_S_KEYS)
  if (typeof s === 'number' && Number.isFinite(s) && s >= 0) {
    // itime-style fields are seconds; values >= 300 are implausibly slow and
    // more likely already milliseconds — keep them as-is rather than x1000.
    return s < 300 ? Math.round(s * 1000) : Math.round(s)
  }
  return null
}

function normUptime(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return Math.round(v * 10) / 10
  const r = asRecord(v)
  if (r) {
    const n = firstPresent(r, UPTIME_NESTED_KEYS)
    if (typeof n === 'number' && Number.isFinite(n)) return Math.round(n * 10) / 10
  }
  return null
}

async function main() {
  console.log(`==> GET ${SOURCE}`)
  // 出境受限机器：SEARXNG_PROXY_URL / HTTPS_PROXY 走代理（原生 fetch 不读 env，
  // socks 需走 lib/host/dispatcher.js 的 bespoke Dispatcher）。
  const proxyUrl = process.env.SEARXNG_PROXY_URL || process.env.HTTPS_PROXY || process.env.https_proxy || ''
  let fetchImpl = fetch
  if (proxyUrl) {
    const { fetch: undiciFetch } = await import('undici')
    const { getOrCreateDispatcher } = await import('../lib/host/dispatcher.js')
    const dispatcher = getOrCreateDispatcher(proxyUrl)
    fetchImpl = (url, init) => undiciFetch(url, { ...init, dispatcher })
    console.log(`via proxy ${proxyUrl.replace(/:[^:@/]+@/, ':***@')}`)
  }
  let res
  try {
    res = await fetchImpl(SOURCE, { headers: { accept: 'application/json', 'user-agent': 'dsh-web-searxng/update-instances' } })
  } catch (e) {
    console.error(`fetch failed: ${String(e)}`)
    console.error('需要能直连 searx.space 的网络（沙箱/受限网络下跑不了）。旧快照保持不动。')
    process.exit(1)
  }
  if (!res.ok) {
    console.error(`HTTP ${res.status} — 旧快照保持不动。`)
    process.exit(1)
  }
  let data
  try {
    data = await res.json()
  } catch (e) {
    console.error(`bad JSON: ${String(e)}`)
    process.exit(1)
  }

  // Top shape is { instances: { url: info } }; tolerate a bare map too.
  const root = asRecord(data)
  const table = asRecord(root?.instances) ?? (root && !Array.isArray(root) ? root : undefined)
  if (!table) {
    console.error('schema 不认识：顶层既没有 instances map 也不是 url→info 的裸 map。')
    console.error(`顶层 keys: ${root ? Object.keys(root).slice(0, 10).join(', ') : '(非对象)'}`)
    process.exit(1)
  }

  const out = []
  for (const [rawUrl, rawInfo] of Object.entries(table)) {
    const url = typeof rawUrl === 'string' ? rawUrl.trim() : ''
    if (!url.startsWith('https://')) continue
    const info = asRecord(rawInfo) ?? {}
    const status = statusFromStats2(info)
    if (status === 'down') continue
    const uptimePct = healthFromStats2(info)
    const latencyMs = latencyFromStats2(info)
    const rawVersion = firstPresent(info, VERSION_KEYS)
    out.push({
      url,
      status,
      uptimePct,
      latencyMs,
      version: typeof rawVersion === 'string' ? rawVersion : null,
    })
  }

  console.log(`up 个数: ${out.filter((i) => i.status === 'up').length}, unknown 个数: ${out.filter((i) => i.status === 'unknown').length}`)
  out.sort((a, b) => {
    if (a.status !== b.status) return a.status === 'up' ? -1 : 1
    if ((b.uptimePct ?? -1) !== (a.uptimePct ?? -1)) return (b.uptimePct ?? -1) - (a.uptimePct ?? -1)
    return (a.latencyMs ?? Infinity) - (b.latencyMs ?? Infinity)
  })
  const kept = out.slice(0, KEEP)

  const snapshot = {
    updatedAt: new Date().toISOString(),
    source: SOURCE,
    note: 'json 可用性 checker 不提供，需保存后 make smoke 自测；社区实例可见查询明文，敏感内容请自建。',
    instances: kept,
  }
  const { writeFile } = await import('node:fs/promises')
  await writeFile(OUT, JSON.stringify(snapshot, null, 2) + '\n')
  console.log(`✓ ${kept.length}/${out.length} 写入 ${new URL(OUT).pathname}`)
  for (const i of kept) {
    console.log(`  - ${i.url} [${i.status}] uptime=${i.uptimePct ?? '?'} latency=${i.latencyMs ?? '?'}ms ${i.version ?? ''}`)
  }
}

await main()
